@Override public FrameworkMuxer create(String path, String outputMimeType) throws IOException {
    try {
        int outputFormat = mimeTypeToMuxerOutputFormat(outputMimeType);
        MediaMuxer mediaMuxer = new MediaMuxer(path, outputFormat);
        return new FrameworkMuxer(mediaMuxer);
    } catch (RuntimeException e) {
        throw new IOException("Failed to create muxer due to invalid mime type: " + outputMimeType, e);
    }
}
